const MILLISECONDS_PER_DAY = 1000 * 60 * 60 * 24

export function signedDifferenceInDays(fromDate, toDate) {
  return (beginningOfDay(toDate) - beginningOfDay(fromDate)) / MILLISECONDS_PER_DAY
}

export function beginningOfDay(date) {
  // Compare local calendar dates as UTC midnights so DST days still count as one day.
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatLocalTime(date, style = "relative", now = new Date()) {
  switch (style) {
    case "time":
      return date.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })
    case "date":
      return date.toLocaleDateString("en-US", { month: "short", day: "numeric" })
    case "long_date":
      return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })
    case "weekday":
      return date.toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric" })
    case "datetime":
      return date.toLocaleString("en-US", { dateStyle: "short", timeStyle: "short" })
    case "relative_date":
      return formatRelativeDate(date, now)
    default:
      if (signedDifferenceInDays(now, date) === 0) {
        return formatLocalTime(date, "time", now)
      } else {
        return formatRelativeDate(date, now)
      }
  }
}

function formatRelativeDate(date, now) {
  const days = signedDifferenceInDays(now, date)

  if (days > -7) {
    return new Intl.RelativeTimeFormat("en", { numeric: "auto" }).format(days, "day")
  } else {
    const options = { month: "short", day: "numeric" }
    if (date.getFullYear() !== now.getFullYear()) options.year = "numeric"
    return date.toLocaleDateString("en-US", options)
  }
}
EOF
